CREATE TABLE customers(id varchar(128) PRIMARY KEY,display_name varchar(255) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','CLOSED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(128) PRIMARY KEY,customer_id varchar(128) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')),version bigint NOT NULL DEFAULT 0,receive_enabled boolean NOT NULL DEFAULT true,public_receive boolean NOT NULL DEFAULT false,transfer_limit numeric(19,3) NOT NULL DEFAULT 10000.000 CHECK(transfer_limit>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(account_id varchar(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,principal varchar(255) NOT NULL,can_debit boolean NOT NULL DEFAULT false,can_receive boolean NOT NULL DEFAULT false,PRIMARY KEY(account_id,principal));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(128) NOT NULL,to_account_id varchar(128) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('PROCESSING','COMPLETED','REJECTED')),rejection_code varchar(64),rejection_http integer,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(255) NOT NULL,correlation_id uuid NOT NULL);
CREATE INDEX payments_source_time ON payments(from_account_id,created_at);CREATE INDEX payments_destination_time ON payments(to_account_id,created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(8) NOT NULL CHECK(entry_type IN ('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE TABLE rate_windows(principal varchar(255) PRIMARY KEY,window_start bigint NOT NULL,request_count integer NOT NULL);
CREATE FUNCTION prevent_financial_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable financial record'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION prevent_financial_mutation();
CREATE FUNCTION protect_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status<>'PROCESSING' THEN RAISE EXCEPTION 'immutable payment'; END IF;IF NEW.payment_id<>OLD.payment_id OR NEW.payload_fingerprint<>OLD.payload_fingerprint OR NEW.requested_by<>OLD.requested_by THEN RAISE EXCEPTION 'immutable identity'; END IF;RETURN NEW; END $$;
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION protect_payment();
CREATE FUNCTION verify_completed_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p uuid; st varchar; n integer; total numeric; BEGIN p:=NEW.payment_id;SELECT status INTO st FROM payments WHERE payment_id=p;IF st='COMPLETED' THEN SELECT count(*),coalesce(sum(signed_amount),0) INTO n,total FROM ledger_entries WHERE payment_id=p;IF n<>2 OR total<>0 OR NOT EXISTS(SELECT 1 FROM ledger_entries l JOIN payments q ON q.payment_id=l.payment_id WHERE q.payment_id=p AND l.entry_type='DEBIT' AND l.account_id=q.from_account_id AND l.signed_amount=-q.amount) OR NOT EXISTS(SELECT 1 FROM ledger_entries l JOIN payments q ON q.payment_id=l.payment_id WHERE q.payment_id=p AND l.entry_type='CREDIT' AND l.account_id=q.to_account_id AND l.signed_amount=q.amount) THEN RAISE EXCEPTION 'unbalanced ledger';END IF;ELSIF st='REJECTED' AND EXISTS(SELECT 1 FROM ledger_entries WHERE payment_id=p) THEN RAISE EXCEPTION 'rejected payment has ledger';ELSIF st='PROCESSING' THEN RAISE EXCEPTION 'unfinished payment';END IF;RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_payment AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_completed_ledger();

CREATE CONSTRAINT TRIGGER balanced_ledger AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_completed_ledger();
